#!/usr/bin/env python3
"""Apply Delimt's website privacy update in a separate Git worktree.

The live Supabase migrations are already applied. This script never executes SQL
and never builds an APK. Run it from the existing Delimt Codespace.
"""
import argparse
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from urllib.parse import urlencode
import zlib

PAYLOAD = json.loads(zlib.decompress(base64.b64decode("")))
TITLE = "Protect account privacy and make referral counting server controlled"
BODY = """Profiles and waitlist records previously allowed broad client access.
The approved live Supabase migrations now enforce profile ownership, prevent
client counter edits, maintain referral credits privately, and publish only
aggregate signup totals. This website update uses the new public counters and
keeps invitation attribution through email confirmation and Google sign-in.

The two migration files record the exact SQL already applied on 21 October 2026.
Do not run them again merely to deploy the website. Their synthetic role checks
passed in the migration transactions: 27 profile checks and 16 waitlist checks.
The source updater also runs the nine referral tests and the Vite production
build before committing. Native Android protection is outside this change.

The existing INSERT-only checkout record remains a lead, not verification of
payment. Other API routes and payment verification are outside this patch.
"""


def command(args, cwd, *, capture=False, check=True):
    result = subprocess.run(args, cwd=cwd, text=True,
                            stdout=subprocess.PIPE if capture else None,
                            stderr=subprocess.PIPE if capture else None)
    if check and result.returncode:
        detail = (result.stderr or result.stdout or "").strip() if capture else ""
        raise RuntimeError("Command failed: " + " ".join(args[:4]) +
                           ("\n" + detail if detail else ""))
    return result


def blob_hash(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()


def apply_files(checkout, payload):
    """Validate every path and baseline before changing any file."""
    writes = []
    for relative, entry in payload.items():
        path = checkout / relative
        if Path(relative).is_absolute() or ".." in Path(relative).parts:
            raise RuntimeError("Unsafe update path")
        for parent in [path, *path.parents]:
            if parent == checkout.parent:
                break
            if parent.is_symlink():
                raise RuntimeError("Refusing a symbolic link: " + relative)
        if path.exists() and not path.is_file():
            raise RuntimeError("Expected a regular file: " + relative)
        current = path.read_bytes() if path.exists() else None
        desired = base64.b64decode(entry["content"])
        if current == desired:
            continue
        current_hash = blob_hash(current) if current is not None else None
        if current_hash != entry["before"]:
            raise RuntimeError(relative + " has changed since review. No update files were changed.")
        writes.append((path, desired))
    for path, desired in writes:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as temp:
            temp.write(desired)
            temporary = Path(temp.name)
        os.replace(temporary, path)
    return len(writes)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prepare-only", action="store_true",
                        help="Write reviewed files only; do not test, commit or push")
    parser.add_argument("--no-push", action="store_true",
                        help="Test and commit locally without pushing or opening a PR")
    options = parser.parse_args()
    root = Path(command(["git", "rev-parse", "--show-toplevel"], Path.cwd(), capture=True).stdout.strip())
    remote = command(["git", "remote", "get-url", "origin"], root, capture=True).stdout.strip()
    if not re.fullmatch(r"(?:https://github\.com/|git@github\.com:)activist015/delimt(?:\.git)?/?", remote, re.I):
        raise RuntimeError("Open the activist015/delimt Codespace before running this update.")

    print("1/4 Preparing a separate website branch. Your current checkout stays in place.", flush=True)
    command(["git", "fetch", "origin", "main"], root)
    checkout = root.parent / "delimt-account-privacy"
    if checkout.exists():
        actual = Path(command(["git", "rev-parse", "--show-toplevel"], checkout, capture=True).stdout.strip())
        branch = command(["git", "branch", "--show-current"], checkout, capture=True).stdout.strip()
        if actual.resolve() != checkout.resolve() or not branch.startswith("fix/account-privacy-"):
            raise RuntimeError("The separate output folder already contains other work. Nothing was overwritten.")
        common = command(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], checkout, capture=True).stdout.strip()
        original = command(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], root, capture=True).stdout.strip()
        if Path(common).resolve() != Path(original).resolve():
            raise RuntimeError("The output folder belongs to another Git repository.")
    else:
        branch = "fix/account-privacy-" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S")
        command(["git", "worktree", "add", "-b", branch, str(checkout), "origin/main"], root)
    changed = command(["git", "diff", "--name-only", "HEAD"], checkout, capture=True).stdout.splitlines()
    untracked = command(["git", "ls-files", "--others", "--exclude-standard"], checkout, capture=True).stdout.splitlines()
    if any(name not in PAYLOAD for name in changed + untracked):
        raise RuntimeError("The separate website branch contains other changes. They were preserved; review them first.")
    count = apply_files(checkout, PAYLOAD)
    print("Reviewed website files ready:", count, "updated.", flush=True)
    print("Website folder:", checkout, flush=True)
    if options.prepare_only:
        print("Prepared only. No tests, commit, push, database change or APK build was run.")
        return

    print("2/4 Running referral tests and the website production build.", flush=True)
    command(["node", "--test", "tests/profile-referral.test.js"], checkout)
    dependencies = checkout / "node_modules"
    original_dependencies = root / "node_modules"
    lock = checkout / "package-lock.json"
    original_lock = root / "package-lock.json"
    if not dependencies.exists():
        if (original_dependencies.is_dir() and lock.is_file() and original_lock.is_file()
                and lock.read_bytes() == original_lock.read_bytes()):
            dependencies.symlink_to(original_dependencies, target_is_directory=True)
        else:
            command(["npm", "ci", "--no-audit", "--no-fund"], checkout)
    command(["npm", "run", "build"], checkout)
    # Commit only this update. Never stage the original Android checkout.
    command(["git", "add", "--", *PAYLOAD.keys()], checkout)
    staged = command(["git", "diff", "--cached", "--name-only"], checkout, capture=True).stdout.splitlines()
    if any(name not in PAYLOAD for name in staged):
        raise RuntimeError("Unexpected staged changes were preserved. No commit was created.")
    if staged:
        command(["git", "commit", "-m", TITLE], checkout)
    if options.no_push:
        print("All checks passed. Local commit ready on", branch)
        return

    print("3/4 Publishing the separate review branch.", flush=True)
    command(["git", "push", "-u", "origin", branch], checkout)
    compare = "https://github.com/activist015/delimt/compare/main..." + branch + "?" + urlencode({"expand": 1, "title": TITLE, "body": BODY})
    pr_url = None
    if shutil.which("gh"):
        existing = command(["gh", "pr", "view", branch, "--json", "url", "--jq", ".url"], checkout, capture=True, check=False)
        if existing.returncode == 0:
            pr_url = existing.stdout.strip()
        else:
            with tempfile.NamedTemporaryFile(mode="w", suffix=".md", delete=False) as temp:
                temp.write(BODY)
                body_path = Path(temp.name)
            try:
                created = command(["gh", "pr", "create", "--draft", "--base", "main", "--head", branch,
                                   "--title", TITLE, "--body-file", str(body_path)], checkout, capture=True, check=False)
                if created.returncode == 0:
                    pr_url = created.stdout.strip()
            finally:
                body_path.unlink(missing_ok=True)
    print("4/4 Website update tested and pushed.")
    print("Open this link to review and merge the website update:")
    print(pr_url or compare)
    print("If the PR is a draft, mark it Ready for review, then merge it after checks pass.")
    print("Vercel will deploy the merged main branch. No new APK or SQL run is needed.")


if __name__ == "__main__":
    try:
        main()
    except (RuntimeError, OSError, ValueError) as error:
        print("\nUpdate paused:", error, file=sys.stderr)
        print("Your original Android checkout was preserved. Share this message for the next step.", file=sys.stderr)
        sys.exit(1)
